INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N061-01','CN0268','S032-01','历史监测及脱氨膜','表3.6-4/5及2017水平衡','两天30个样品各6指标，共180原始测项；2016监测各点不能与2017脱氨膜性能直接计算去除率。原表个别均值与单次值不符（如TP .37与约.037），保留原始样品，不擅改原表。2017报告明确洗涤废水脱氨膜酸吸收回用，与产品膜过滤和纯水RO区分；膜材质、通量、酸液去向未知。原文截图超时，正文可读。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N061-02','CN0288','S061-01','设施和许可边界','p10及许可信息','申请材料披露新建3套洗涤塔及三效强制蒸发3t/h；碱吸收SO2、CO2产生含盐废水，称该再生范围无其他工艺废水。细粉及瓷球委托有资质单位，不当蒸发盐。既有5900t/a经营规模不重复；许可有效期2023-08-07至2028-08-06，省外≤50%；拟转移约80吨不当实际接收。p10截图核实。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N061-03','CN0288','S060-11','独立跨省转移许可','2025年11月公告','中化泉州碳三加氢废催化剂向岳阳长旺15吨，许可至2025-12-31，非实际接收。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N061-04','CN0221','S061-02','碱溶废水设备采购','采购公告','预算170万元含税，采购范围包含设计、设备供货与控制等；未披露水量、工艺和膜类型。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N061-05','CN0221','S061-03','采购成交','成交公告','湖南晟邦环保科技有限公司成交165万元；公告转载，未证明实际安装、付款、投运或处理效果。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N061-06','CN0221','S061-04','生活污水依托设施','2023审批污水段','隔油池48m³、化粪池70m³，生活污水处理设施120m³/d；其他项目依托，不归为生产废水站。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N061-07','CN0214','W05S04','设计设备和污染负荷','§4.4.2 表4.4-1/2','原报告另一路径可读；旧7股废水及16浓度不重复。蒸氨5t/h、200h/a、1000t/a，两40m³滤水槽；总5566.69t/a，处理回用1678.69、进入站3888。分项铬负荷与汇总差异不强行平衡。截图未取得。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N061-08','CN0214','S061-05','排污许可摘要','许可检索结果','企业COD许可33.832t/a、氨氮3.568t/a；原页超时，许可期和单线分配未核。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N061-09','CN0251','S061-08','新厂区及项目边界','拟审批废水段','涉及催化剂制备/水解气等环节，但主产品14000t/a R113a不当催化剂产能；旧7000互备不能相加。新厂区除氟絮凝、MVR、后续芬顿絮凝活性炭及A²/O，独立冷却除氟。旧厂DW005实际排放记录不移植。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N061-10','CN0251','S061-09','R32项目验收线索','行业报道检索摘要','报道提及2026-03验收公示，正文跳转未取得；不判为验收通过或新R113a已运行。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N061-11','CN0301','S061-10','调试公示','公告','2026-10-13至11-13环保设备调试；建设单位写辽阳市博鑫化工厂，与公司标题名称有差异，芳烃基地万和二路2-3号匹配；待主体关系与验收确认。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N061-12','CN0302','turn787991search0','经营许可正式发放','辽宁许可公告','LN2110040046，2026-11-06至2031-11-05；铂400、银500t/a，正式许可非产量或投运。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N061-13','CN0217','S061-11','历史经营许可','历史许可清单检索摘要','3311000198，800t/a HW50，遂昌工业园区龙板山区块，所列有效期截至2025-11-03；不证明2026持证或实际接收。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N061-14','CN0068','S061-12','同行环评引用建设状态','同类项目表检索摘要','同行环评列2024-05审批、已批在建、2万t/a SCR（不含垃圾及危废焚烧）；属同行引用，与集团4万口径不同，不叠加；当前验收未核。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
